def build_3slide_script():
    return '''<script id="cdil-hero-slideshow-script">
/* CDIL Hero Automatic Slideshow & Synchronized Featured Project Card & Smooth Scroll */
(function initCDILHeroSlideshow() {
  function setupSlideshow() {
    var bgSlides = document.querySelectorAll('.cdil-hero-slide-bg');
    var cardSlides = document.querySelectorAll('.cdil-card-slide');
    var slideBars = document.querySelectorAll('.cdil-slide-bar');
    var badgeEl = document.getElementById('cdil-hero-card-badge');

    if (!bgSlides.length || !cardSlides.length) return;

    var labels = ['Ongoing Project', 'Ongoing Project', 'Completed Project'];
    var currentIndex = 0;
    var timer = null;
    var slideDuration = 5500; // 5.5 seconds per slide for smooth breathing room

    function showSlide(index) {
      if (index < 0 || index >= bgSlides.length) return;
      currentIndex = index;

      // Crossfade background images
      for (var i = 0; i < bgSlides.length; i++) {
        if (i === currentIndex) {
          bgSlides[i].classList.add('active');
          bgSlides[i].setAttribute('aria-hidden', 'false');
          var img = bgSlides[i].querySelector('img');
          if (img) {
            img.style.animation = 'none';
            void img.offsetWidth; // trigger reflow
            img.style.animation = 'hsZoom-Rqc6lp 9.3s linear forwards';
          }
        } else {
          bgSlides[i].classList.remove('active');
          bgSlides[i].setAttribute('aria-hidden', 'true');
        }
      }

      // Synchronize featured card property info
      for (var j = 0; j < cardSlides.length; j++) {
        if (j === currentIndex) {
          cardSlides[j].classList.add('active');
        } else {
          cardSlides[j].classList.remove('active');
        }
      }

      // Synchronize top-right project label badge
      if (badgeEl && labels[currentIndex]) {
        badgeEl.style.opacity = '0';
        (function(lbl) {
          setTimeout(function() {
            badgeEl.textContent = lbl;
            badgeEl.style.opacity = '1';
          }, 250);
        })(labels[currentIndex]);
      }

      // Synchronize progress indicator bars
      for (var k = 0; k < slideBars.length; k++) {
        if (k === currentIndex) {
          slideBars[k].classList.add('active');
        } else {
          slideBars[k].classList.remove('active');
        }
      }
    }

    function nextSlide() {
      var next = (currentIndex + 1) % bgSlides.length;
      showSlide(next);
    }

    function startAutoplay() {
      stopAutoplay();
      timer = setInterval(nextSlide, slideDuration);
    }

    function stopAutoplay() {
      if (timer) {
        clearInterval(timer);
        timer = null;
      }
    }

    // Preload slide images to eliminate flicker or layout shifts
    for (var m = 0; m < bgSlides.length; m++) {
      var slideImg = bgSlides[m].querySelector('img');
      if (slideImg && slideImg.src) {
        var preloader = new Image();
        preloader.src = slideImg.src;
      }
    }

    // Allow user to click any indicator bar to jump directly to that slide
    for (var n = 0; n < slideBars.length; n++) {
      (function(idx) {
        slideBars[idx].addEventListener('click', function(e) {
          e.stopPropagation();
          showSlide(idx);
          startAutoplay();
        });
      })(n);
    }

    // Start auto transition
    startAutoplay();

    // Pause on tab switch, resume on return
    document.addEventListener('visibilitychange', function() {
      if (document.hidden) {
        stopAutoplay();
      } else {
        startAutoplay();
      }
    });

    // Wire up "View Projects" button for guaranteed smooth scroll to #our-projects
    var viewProjectsBtn = document.querySelector('a[data-framer-name="View Projects Button"]');
    if (viewProjectsBtn) {
      viewProjectsBtn.addEventListener('click', function(e) {
        var targetSec = document.getElementById('our-projects');
        if (targetSec) {
          e.preventDefault();
          targetSec.scrollIntoView({ behavior: 'smooth', block: 'start' });
          if (history.pushState) {
            history.pushState(null, null, '#our-projects');
          }
        }
      });
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', setupSlideshow);
  } else {
    setupSlideshow();
  }
})();
</script>'''

